// --- SISTEMA DE ARMAZENAMENTO POR DIA ---
function getChaveHoje() {
  const hoje = new Date();
    const dia = String(hoje.getDate()).padStart(2, '0');
      const mes = String(hoje.getMonth() + 1).padStart(2, '0');
        const ano = hoje.getFullYear();
          return `PNAE_REGISTROS_${dia}/${mes}/${ano}`;
          }

          function carregarAtendimentos() {
            const chave = getChaveHoje();
              const dados = localStorage.getItem(chave);
                return dados ? JSON.parse(dados) : [];
                }

                function salvarAtendimentos(lista) {
                  const chave = getChaveHoje();
                    localStorage.setItem(chave, JSON.stringify(lista));
                    }

                    // Auxiliar para calcular minutos decorridos
                    function calcularMinutosEsperando(timestampCriacao) {
                      const agora = Date.now();
                        const diffMs = agora - timestampCriacao;
                          return Math.max(0, Math.floor(diffMs / 60000));
                          }

                          // --- PÁGINA DO AGENTE (index.html) ---
                          const formAtendimento = document.getElementById('formAtendimento');
                          if (formAtendimento) {
                            const listaAtivos = document.getElementById('listaAtivos');
                              const badgeAtivos = document.getElementById('badgeAtivos');
                                const chatLogs = document.getElementById('chatLogs');
                                  const chatInput = document.getElementById('chatInput');
                                    const btnEnviarChat = document.getElementById('btnEnviarChat');
                                      const btnRegistrarPendente = document.getElementById('btnRegistrarPendente');

                                        function renderizarAgente() {
                                            const todos = carregarAtendimentos();
                                                const ativosEPendentes = todos.filter(item => item.status === 'Em Andamento' || item.status === 'Pendente');

                                                    if (badgeAtivos) badgeAtivos.textContent = ativosEPendentes.length;

                                                        if (!listaAtivos) return;

                                                            if (ativosEPendentes.length === 0) {
                                                                  listaAtivos.innerHTML = '<p class="empty-msg">Nenhum atendimento ativo no momento.</p>';
                                                                        return;
                                                                            }

                                                                                listaAtivos.innerHTML = ativosEPendentes.slice().reverse().map(item => {
                                                                                      const isPendente = item.status === 'Pendente';

                                                                                            if (isPendente) {
                                                                                                    const minEsperando = calcularMinutosEsperando(item.timestampCriacao);
                                                                                                            return `
                                                                                                                      <div class="item-ativo-card card-status-pendente">
                                                                                                                                  <div class="item-ativo-header">
                                                                                                                                                <span class="item-ativo-nome">${item.cliente}</span>
                                                                                                                                                              <span class="item-ativo-tag tag-pendente">⚠️ PENDENTE</span>
                                                                                                                                                                          </div>
                                                                                                                                                                                      <div class="item-ativo-rota">✈️ Voo: <b>${item.voo}</b> | 🏷️ Tipo: <b>${item.tipo}</b></div>
                                                                                                                                                                                                  <div class="item-ativo-hora" style="color: #dc2626; font-weight: 800; font-size: 0.9rem; margin-top: 4px;">
                                                                                                                                                                                                                ⏱️ Aguardando agente há ${minEsperando} min (Solicitado às ${item.horaInicio})
                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                        <button class="btn-assumir-card" onclick="assumirAtendimento('${item.id}')">➕ INICIAR ESTE ATENDIMENTO AGORA</button>
                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                          `;
                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                        return `
                                                                                                                                                                                                                                                                                  <div class="item-ativo-card">
                                                                                                                                                                                                                                                                                              <div class="item-ativo-header">
                                                                                                                                                                                                                                                                                                            <span class="item-ativo-nome">${item.cliente}</span>
                                                                                                                                                                                                                                                                                                                          <span class="item-ativo-tag">${item.tipo}</span>
                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                  <div class="item-ativo-rota">✈️ Voo: <b>${item.voo}</b> | 👤 Agente: <b>${item.agente || '-'}</b></div>
                                                                                                                                                                                                                                                                                                                                                              <div class="item-ativo-rota">📍 <b>${item.origem || 'Pátio'}</b> ➔ <b>${item.destino || 'Destino'}</b></div>
                                                                                                                                                                                                                                                                                                                                                                          <div class="item-ativo-hora">⏱️ Início do Serviço: ${item.horaInicio}</div>
                                                                                                                                                                                                                                                                                                                                                                                      <button class="btn-finalizar-card" onclick="finalizarAtendimento('${item.id}')">✔ FINALIZAR ESTE SERVIÇO</button>
                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                        `;
                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                  }).join('');
                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                      // 1. Início Directo (Preenchendo tudo na hora)
                                                                                                                                                                                                                                                                                                                                                                                                                        formAtendimento.addEventListener('submit', (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                            e.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                const agente = document.getElementById('agenteNome').value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                    const origem = document.getElementById('origem').value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                        const destino = document.getElementById('destino').value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!agente || !origem || !destino) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                  alert("Para iniciar direto, informe Nome do Agente, Origem e Destino.\n\nSe não houver colaborador pronto, clique no botão amarelo 'DEIXAR PENDENTE'.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                const agora = Date.now();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const novo = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          id: agora.toString(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                agente: agente,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      voo: document.getElementById('vooNumero').value.trim().toUpperCase(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cliente: document.getElementById('clienteNome').value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  tipo: document.getElementById('pnaeTipo').value.trim().toUpperCase(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        origem: origem,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              destino: destino,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    status: 'Em Andamento',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          horaInicio: new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                timestampCriacao: agora,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      timestampInicio: agora,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            horaFim: '-',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  duracao: '-',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        observacao: 'Atendimento Iniciado Directo'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const todos = carregarAtendimentos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    todos.push(novo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        salvarAtendimentos(todos);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            formAtendimento.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                renderizarAgente();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 2. Registrar Pendente (Apenas Cliente, Voo e Tipo)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (btnRegistrarPendente) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          btnRegistrarPendente.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const cliente = document.getElementById('clienteNome').value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const voo = document.getElementById('vooNumero').value.trim().toUpperCase();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const tipo = document.getElementById('pnaeTipo').value.trim().toUpperCase();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!cliente || !voo || !tipo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          alert("Para criar solicitação pendente, informe: Nome do Cliente, Nº do Voo e Tipo de Serviço.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const agora = Date.now();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const novoPendente = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            id: agora.toString(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    agente: 'Aguardando...',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            voo: voo,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cliente: cliente,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tipo: tipo,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    origem: 'Aguardando Agente',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            destino: 'Aguardando Agente',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    status: 'Pendente',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            horaInicio: new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    timestampCriacao: agora,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            timestampInicio: null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    horaFim: '-',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            duracao: '-',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    observacao: 'Solicitação Criada (Pendente)'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const todos = carregarAtendimentos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      todos.push(novoPendente);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            salvarAtendimentos(todos);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  formAtendimento.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        renderizarAgente();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 3. Clique no Card Pendente para Iniciar/Assumir
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  window.assumirAtendimento = function(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const nomeAgente = prompt("Digite seu NOME / RE para iniciar este atendimento:");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!nomeAgente || !nomeAgente.trim()) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const origem = prompt("Digite a ORIGEM (Ex: Check-in, Gate 02):") || "Check-in";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const destino = prompt("Digite o DESTINO (Ex: Finger 08, Aeronave):") || "Aeronave";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const todos = carregarAtendimentos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const item = todos.find(a => a.id === id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const agora = Date.now();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const esperaMin = Math.max(0, Math.floor((agora - item.timestampCriacao) / 60000));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                item.agente = nomeAgente.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      item.origem = origem.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            item.destino = destino.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  item.status = 'Em Andamento';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        item.timestampInicio = agora;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              item.horaInicio = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    item.observacao = `Assumido após ${esperaMin} min de espera`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          salvarAtendimentos(todos);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                renderizarAgente();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 4. Finalizar Atendimento
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          window.finalizarAtendimento = function(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const todos = carregarAtendimentos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const item = todos.find(a => a.id === id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const agora = Date.now();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const diffMinutos = Math.max(1, Math.round((agora - (item.timestampInicio || item.timestampCriacao)) / 60000));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        item.status = 'Concluído';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              item.horaFim = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    item.duracao = `${diffMinutos} min`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          item.duracaoNum = diffMinutos;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                salvarAtendimentos(todos);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      renderizarAgente();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (btnEnviarChat && chatInput) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  btnEnviarChat.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const texto = chatInput.value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (texto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const hora = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const div = document.createElement('div');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      div.className = 'msg';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              div.innerHTML = `<strong>[${hora}]:</strong> ${texto}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      chatLogs.appendChild(div);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              chatLogs.scrollTop = chatLogs.scrollHeight;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      chatInput.value = '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    renderizarAgente();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      setInterval(renderizarAgente, 5000); // Atualiza os timers a cada 5s
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // --- PAINEL DE CONTROLE (controle.html) ---
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const tabelaCorpo = document.getElementById('tabelaCorpo');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (tabelaCorpo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function renderizarPainel() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const todos = carregarAtendimentos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const countPendentes = document.getElementById('countPendentes');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const countAndamento = document.getElementById('countAndamento');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const countConcluidos = document.getElementById('countConcluidos');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const tempoMedioGeral = document.getElementById('tempoMedioGeral');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const pendentes = todos.filter(a => a.status === 'Pendente');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const emAndamento = todos.filter(a => a.status === 'Em Andamento');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const concluidos = todos.filter(a => a.status === 'Concluído');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (countPendentes) countPendentes.textContent = pendentes.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (countAndamento) countAndamento.textContent = emAndamento.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (countConcluidos) countConcluidos.textContent = concluidos.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (tempoMedioGeral) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (concluidos.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      tempoMedioGeral.textContent = '0 min';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const somaMinutos = concluidos.reduce((acc, item) => acc + (item.duracaoNum || 0), 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const media = Math.round(somaMinutos / concluidos.length);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tempoMedioGeral.textContent = `${media} min`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (todos.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tabelaCorpo.innerHTML = '<tr><td colspan="10" style="text-align:center; color:#94a3b8; padding:20px;">Nenhum atendimento registrado hoje.</td></tr>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      tabelaCorpo.innerHTML = todos.slice().reverse().map(item => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const isPendente = item.status === 'Pendente';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let statusTexto = item.status;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              let duracaoDisplay = item.duracao;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (isPendente) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const minEsperando = calcularMinutosEsperando(item.timestampCriacao);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    statusTexto = `PENDENTE (${minEsperando}m)`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            duracaoDisplay = `Aguardando ${minEsperando} min`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const rowStyle = isPendente ? 'style="background-color: rgba(239, 68, 68, 0.22); border-left: 5px solid #ef4444;"' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const statusBg = isPendente ? '#ef4444' : (item.status === 'Em Andamento' ? '#0284c7' : '#10b981');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <tr ${rowStyle}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <td><strong>${item.voo || '-'}</strong></td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <td>${item.cliente || '-'}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <td><span class="badge-pnae">${item.tipo || '-'}</span></td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <td>${item.origem || '-'} ➔ ${item.destino || '-'}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <td><strong>${item.agente || '-'}</strong></td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span class="status-tag" style="background-color: ${statusBg}; ${isPendente ? 'animation: piscar 1.2s infinite;' : ''}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ${statusTexto}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <td>${item.horaInicio || '-'}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <td>${item.horaFim || '-'}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <td><strong>${duracaoDisplay}</strong></td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <td>${item.observacao || '-'}</td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }).join('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      renderizarPainel();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setInterval(renderizarPainel, 3000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        